using System;
using Xunit;

public class DoorstopTests
{
    [Fact]
    public void TC_001_StoreRequirements_PermanentlyAndSecurely()
    {
        // Arrange
        var doorstop = new Doorstop();
        var requirement = "Requirement 1";

        // Act
        doorstop.StoreRequirement(requirement);

        // Assert
        Assert.True(doorstop.IsRequirementStored(requirement));
    }

    [Fact]
    public void TC_002_HandleChangeManagement()
    {
        // Arrange
        var doorstop = new Doorstop();
        var requirement = "Requirement 1";
        var newRequirement = "Updated Requirement 1";

        // Act
        doorstop.StoreRequirement(requirement);
        doorstop.UpdateRequirement(requirement, newRequirement);

        // Assert
        Assert.True(doorstop.IsRequirementStored(newRequirement));
    }

    [Fact]
    public void TC_003_AssociateRequirementsChangesToDeveloper()
    {
        // Arrange
        var doorstop = new Doorstop();
        var requirement = "Requirement 1";
        var developer = "Developer1";

        // Act
        doorstop.StoreRequirement(requirement);
        doorstop.AssociateDeveloperWithRequirement(requirement, developer);

        // Assert
        Assert.Equal(developer, doorstop.GetDeveloperForRequirement(requirement));
    }

    [Fact]
    public void TC_004_ScaleToSupportThousandsOfRequirements()
    {
        // Arrange
        var doorstop = new Doorstop();
        var requirements = new List<string>();
        for (int i = 0; i < 1000; i++)
        {
            requirements.Add($"Requirement {i}");
        }

        // Act
        foreach (var requirement in requirements)
        {
            doorstop.StoreRequirement(requirement);
        }

        // Assert
        Assert.Equal(1000, doorstop.GetNumberOfRequirements());
    }

    [Fact]
    public void TC_005_ProvideLightweightInstallationMethod()
    {
        // Arrange
        var doorstop = new Doorstop();

        // Act
        doorstop.Install();

        // Assert
        Assert.True(doorstop.IsInstalled());
    }
}
